const providerIssuerCrypto = require('crypto');
const PROVIDER_ISSUER_REQUIRED_SCOPE = 'salesforce.integration';
const PROVIDER_ISSUER_TOKEN_TTL_SECONDS = 900;

function providerIssuerEnv(name) {
  try { return String($env[name] || ''); } catch (error) { return ''; }
}

function providerIssuerHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}

function providerIssuerScopes(value) {
  return [...new Set(String(value || '').trim().split(/\s+/).filter(Boolean))];
}

function providerIssuerResponse(statusCode, body, invalidClient = false) {
  return [{ json: { statusCode, body, invalidClient } }];
}

function providerIssuerError(statusCode, error, description, invalidClient = false) {
  return providerIssuerResponse(statusCode, { error, error_description: description }, invalidClient);
}

function providerIssuerIsDigest(value) {
  return /^[a-f0-9]{64}$/i.test(String(value || ''));
}

function providerIssuerTextEquals(candidate, expected) {
  const left = providerIssuerCrypto.createHash('sha256').update(String(candidate || ''), 'utf8').digest();
  const right = providerIssuerCrypto.createHash('sha256').update(String(expected || ''), 'utf8').digest();
  return providerIssuerCrypto.timingSafeEqual(left, right);
}

function providerIssuerSecretMatches(candidate, expectedDigest) {
  const digestIsValid = providerIssuerIsDigest(expectedDigest);
  const candidateDigest = providerIssuerCrypto.createHash('sha256').update(String(candidate || ''), 'utf8').digest();
  const expected = digestIsValid ? Buffer.from(String(expectedDigest), 'hex') : Buffer.alloc(32);
  const matches = providerIssuerCrypto.timingSafeEqual(candidateDigest, expected);
  return Boolean(candidate) && digestIsValid && matches;
}

function providerIssuerDecodeBasic(authorization) {
  const match = String(authorization || '').match(/^Basic[ \t]+([A-Za-z0-9+/]*={0,2})[ \t]*$/i);
  if (!match || !match[1] || match[1].length % 4 === 1) return null;
  try {
    const encoded = match[1];
    const decodedBuffer = Buffer.from(encoded, 'base64');
    if (decodedBuffer.toString('base64').replace(/=+$/, '') !== encoded.replace(/=+$/, '')) return null;
    const decoded = decodedBuffer.toString('utf8');
    const separator = decoded.indexOf(':');
    if (separator <= 0) return null;
    return { clientId: decoded.slice(0, separator), clientSecret: decoded.slice(separator + 1) };
  } catch (error) {
    return null;
  }
}

function providerIssuerField(body, name) {
  const value = body[name];
  return Array.isArray(value) ? value[0] : value;
}

function providerIssuerBase64Url(value) {
  return Buffer.from(value).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function providerIssuerReadConfig() {
  const clientId = providerIssuerEnv('RENOV_OAUTH_CLIENT_ID');
  const currentDigest = providerIssuerEnv('RENOV_OAUTH_CLIENT_SECRET_SHA256');
  const previousDigest = providerIssuerEnv('RENOV_OAUTH_CLIENT_SECRET_SHA256_PREVIOUS');
  const jwtSecret = providerIssuerEnv('RENOV_OAUTH_JWT_SECRET');
  const issuer = providerIssuerEnv('RENOV_OAUTH_ISSUER');
  const audience = providerIssuerEnv('RENOV_OAUTH_AUDIENCE');
  const configuredScope = providerIssuerEnv('RENOV_OAUTH_SCOPE');
  const allowedClientIds = providerIssuerEnv('RENOV_PROVIDER_CLIENT_IDS')
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);
  const configuredScopes = providerIssuerScopes(configuredScope);
  const valid = Boolean(
    clientId
    && providerIssuerIsDigest(currentDigest)
    && (!previousDigest || providerIssuerIsDigest(previousDigest))
    && jwtSecret
    && issuer
    && audience
    && configuredScopes.includes(PROVIDER_ISSUER_REQUIRED_SCOPE)
    && allowedClientIds.length > 0
  );
  return {
    valid,
    clientId,
    currentDigest,
    previousDigest,
    jwtSecret,
    issuer,
    audience,
    configuredScopes,
  };
}

const providerIssuerRequest = $input.first().json || {};
const providerIssuerHeaders = providerIssuerRequest.headers || {};
const providerIssuerBody = providerIssuerRequest.body;
const providerIssuerConfig = providerIssuerReadConfig();

if (!providerIssuerConfig.valid) {
  return providerIssuerError(503, 'server_error', 'OAuth server configuration is unavailable.');
}
if (!providerIssuerBody || typeof providerIssuerBody !== 'object' || Array.isArray(providerIssuerBody)) {
  return providerIssuerError(400, 'invalid_request', 'A JSON or form request body is required.');
}

const providerIssuerAuthorization = providerIssuerHeader(providerIssuerHeaders, 'authorization');
const providerIssuerHasBodyCredentials = Object.prototype.hasOwnProperty.call(providerIssuerBody, 'client_id')
  || Object.prototype.hasOwnProperty.call(providerIssuerBody, 'client_secret');
let providerIssuerCredentials;

if (providerIssuerAuthorization) {
  providerIssuerCredentials = providerIssuerDecodeBasic(providerIssuerAuthorization);
  if (!providerIssuerCredentials) {
    return providerIssuerError(401, 'invalid_client', 'Client authentication failed.', true);
  }
  if (providerIssuerHasBodyCredentials) {
    return providerIssuerError(400, 'invalid_request', 'Use one client authentication method only.');
  }
} else {
  providerIssuerCredentials = {
    clientId: providerIssuerField(providerIssuerBody, 'client_id'),
    clientSecret: providerIssuerField(providerIssuerBody, 'client_secret'),
  };
}

const providerIssuerClientId = String(providerIssuerCredentials.clientId || '');
const providerIssuerClientSecret = String(providerIssuerCredentials.clientSecret || '');
const providerIssuerIdMatches = providerIssuerTextEquals(providerIssuerClientId, providerIssuerConfig.clientId);
const providerIssuerCurrentMatches = providerIssuerSecretMatches(
  providerIssuerClientSecret,
  providerIssuerConfig.currentDigest,
);
const providerIssuerPreviousMatches = providerIssuerSecretMatches(
  providerIssuerClientSecret,
  providerIssuerConfig.previousDigest,
);

if (!providerIssuerIdMatches || (!providerIssuerCurrentMatches && !providerIssuerPreviousMatches)) {
  return providerIssuerError(401, 'invalid_client', 'Client authentication failed.', true);
}

const providerIssuerGrantType = String(providerIssuerField(providerIssuerBody, 'grant_type') || '').trim();
if (providerIssuerGrantType !== 'client_credentials') {
  return providerIssuerError(400, 'unsupported_grant_type', 'grant_type must be client_credentials.');
}

const providerIssuerRequestedScopes = providerIssuerScopes(providerIssuerField(providerIssuerBody, 'scope'));
const providerIssuerScopeIsValid = providerIssuerRequestedScopes.includes(PROVIDER_ISSUER_REQUIRED_SCOPE)
  && providerIssuerRequestedScopes.every((scope) => providerIssuerConfig.configuredScopes.includes(scope));
if (!providerIssuerScopeIsValid) {
  return providerIssuerError(400, 'invalid_scope', 'The requested scope is invalid or insufficient.');
}

const providerIssuerNow = Math.floor(Date.now() / 1000);
const providerIssuerGrantedScope = providerIssuerRequestedScopes.join(' ');
const providerIssuerHeaderJson = { alg: 'HS256', typ: 'JWT' };
const providerIssuerPayload = {
  iss: providerIssuerConfig.issuer,
  aud: providerIssuerConfig.audience,
  sub: providerIssuerConfig.clientId,
  client_id: providerIssuerConfig.clientId,
  scope: providerIssuerGrantedScope,
  iat: providerIssuerNow,
  nbf: providerIssuerNow,
  exp: providerIssuerNow + PROVIDER_ISSUER_TOKEN_TTL_SECONDS,
};
const providerIssuerHeaderPart = providerIssuerBase64Url(JSON.stringify(providerIssuerHeaderJson));
const providerIssuerPayloadPart = providerIssuerBase64Url(JSON.stringify(providerIssuerPayload));
const providerIssuerSigningInput = providerIssuerHeaderPart + '.' + providerIssuerPayloadPart;
const providerIssuerSignature = providerIssuerCrypto
  .createHmac('sha256', providerIssuerConfig.jwtSecret)
  .update(providerIssuerSigningInput, 'utf8')
  .digest();
const providerIssuerAccessToken = providerIssuerSigningInput + '.' + providerIssuerBase64Url(providerIssuerSignature);

return providerIssuerResponse(200, {
  access_token: providerIssuerAccessToken,
  token_type: 'Bearer',
  expires_in: PROVIDER_ISSUER_TOKEN_TTL_SECONDS,
  scope: providerIssuerGrantedScope,
});

const providerOAuthCrypto = require('crypto');
const PROVIDER_OAUTH_REQUIRED_SCOPE = 'salesforce.integration';
const PROVIDER_OAUTH_TOKEN_TTL_SECONDS = 900;

function providerOAuthEnv(name) {
  try { return String($env[name] || ''); } catch (error) { return ''; }
}

function providerOAuthHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}

function providerOAuthScopes(value) {
  return [...new Set(String(value || '').trim().split(/\s+/).filter(Boolean))];
}

function providerOAuthBase64Url(value) {
  return Buffer.from(value).toString('base64').replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

function providerOAuthDecodeSegment(segment) {
  if (!/^[A-Za-z0-9_-]+$/.test(String(segment || ''))) throw new Error('invalid base64url');
  const padding = (4 - (segment.length % 4)) % 4;
  const decoded = Buffer.from(segment + '='.repeat(padding), 'base64');
  if (providerOAuthBase64Url(decoded) !== segment) throw new Error('non-canonical base64url');
  return decoded;
}

function providerOAuthFailure(statusCode, error, description) {
  return { ok: false, statusCode, body: { error, error_description: description } };
}

function providerOAuthInvalidToken() {
  return providerOAuthFailure(401, 'invalid_token', 'The access token is invalid or expired.');
}

function validateProviderBearerJwt(request) {
  const jwtSecret = providerOAuthEnv('RENOV_OAUTH_JWT_SECRET');
  const issuer = providerOAuthEnv('RENOV_OAUTH_ISSUER');
  const audience = providerOAuthEnv('RENOV_OAUTH_AUDIENCE');
  const configuredClientId = providerOAuthEnv('RENOV_OAUTH_CLIENT_ID');
  const configuredScopes = providerOAuthScopes(providerOAuthEnv('RENOV_OAUTH_SCOPE'));
  const allowedClientIds = providerOAuthEnv('RENOV_PROVIDER_CLIENT_IDS')
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);

  if (!jwtSecret || !issuer || !audience || !configuredClientId
      || !configuredScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || allowedClientIds.length === 0) {
    return providerOAuthFailure(503, 'server_error', 'OAuth server configuration is unavailable.');
  }

  const headers = request && request.headers && typeof request.headers === 'object' ? request.headers : {};
  const authorization = String(providerOAuthHeader(headers, 'authorization') || '');
  const bearerMatch = authorization.match(/^Bearer[ \t]+([^ \t]+)[ \t]*$/i);
  const xClientId = String(providerOAuthHeader(headers, 'x-client-id') || '').trim().toLowerCase();
  if (!bearerMatch || !xClientId || !allowedClientIds.includes(xClientId)) return providerOAuthInvalidToken();

  const token = bearerMatch[1];
  const parts = token.split('.');
  if (parts.length !== 3) return providerOAuthInvalidToken();

  let header;
  let payload;
  let signature;
  try {
    header = JSON.parse(providerOAuthDecodeSegment(parts[0]).toString('utf8'));
    payload = JSON.parse(providerOAuthDecodeSegment(parts[1]).toString('utf8'));
    signature = providerOAuthDecodeSegment(parts[2]);
  } catch (error) {
    return providerOAuthInvalidToken();
  }
  if (!header || typeof header !== 'object' || Array.isArray(header) || header.alg !== 'HS256') {
    return providerOAuthInvalidToken();
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return providerOAuthInvalidToken();

  const expectedSignature = providerOAuthCrypto
    .createHmac('sha256', jwtSecret)
    .update(parts[0] + '.' + parts[1], 'utf8')
    .digest();
  if (signature.length !== expectedSignature.length
      || !providerOAuthCrypto.timingSafeEqual(signature, expectedSignature)) {
    return providerOAuthInvalidToken();
  }

  if (payload.iss !== issuer || payload.aud !== audience
      || typeof payload.sub !== 'string' || typeof payload.client_id !== 'string'
      || payload.sub !== configuredClientId || payload.client_id !== configuredClientId
      || payload.sub !== payload.client_id) {
    return providerOAuthInvalidToken();
  }

  const tokenScopes = providerOAuthScopes(payload.scope);
  if (!tokenScopes.includes(PROVIDER_OAUTH_REQUIRED_SCOPE)
      || !tokenScopes.every((scope) => configuredScopes.includes(scope))) {
    return providerOAuthFailure(403, 'insufficient_scope', 'The access token lacks the required scope.');
  }

  const numericDatesAreValid = Number.isSafeInteger(payload.iat)
    && Number.isSafeInteger(payload.nbf)
    && Number.isSafeInteger(payload.exp);
  const now = Math.floor(Date.now() / 1000);
  if (!numericDatesAreValid
      || payload.nbf !== payload.iat
      || payload.exp - payload.iat !== PROVIDER_OAUTH_TOKEN_TTL_SECONDS
      || payload.iat > now
      || payload.nbf > now
      || payload.exp <= now) {
    return providerOAuthInvalidToken();
  }

  return {
    ok: true,
    clientId: payload.client_id,
    providerClientId: xClientId,
    scope: tokenScopes.join(' '),
    claims: payload,
  };
}

const providerOAuthRequest = $input.first().json || {};
const providerOAuthAuth = validateProviderBearerJwt(providerOAuthRequest);
if (!providerOAuthAuth.ok) {
  return [{ json: { statusCode: providerOAuthAuth.statusCode, body: providerOAuthAuth.body, authorized: false } }];
}

return [{
  json: {
    statusCode: 200,
    authorized: true,
    body: {
      active: true,
      token_type: 'Bearer',
      client_id: providerOAuthAuth.clientId,
      provider_client_id: providerOAuthAuth.providerClientId,
      scope: providerOAuthAuth.scope,
      expires_at: providerOAuthAuth.claims.exp,
    },
  },
}];
